import * as THREE from '../vendor/three.module.js';
const eps=1e-6;
const area=p=>Math.abs(p.reduce((n,v,i)=>{const w=p[(i+1)%p.length];return n+v[0]*w[1]-v[1]*w[0];},0))/2;
function clip(poly,axis,value,inside){const out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],da=(a[axis]-value)*inside,db=(b[axis]-value)*inside;if(da>=-1e-9)out.push(a);if((da<0)!==(db<0)){const t=da/(da-db);out.push([a[0]+t*(b[0]-a[0]),a[1]+t*(b[1]-a[1])]);}}return out;}
function subtract(poly,r){if(Math.max(...poly.map(v=>v[0]))<=r[0]+eps||Math.min(...poly.map(v=>v[0]))>=r[2]-eps||Math.max(...poly.map(v=>v[1]))<=r[1]+eps||Math.min(...poly.map(v=>v[1]))>=r[3]-eps)return[poly];const out=[];let left=poly;for(const [axis,value,inside]of[[0,r[0],1],[0,r[2],-1],[1,r[1],1],[1,r[3],-1]]){if(left.length<3)break;const outside=clip(left,axis,value,-inside);if(outside.length>=3&&area(outside)>1e-9)out.push(outside);left=clip(left,axis,value,inside);if(area(left)<1e-9)break;}return out;}
// Axis walls own shared horizontal caps at diagonal T-junctions. Keep the
// diagonal side walls and cut only the overlapped cap area, without moving walls.
export function clipDiagonalCaps(root,excluded,{force=false}={}){const inverse=root.matrixWorld.clone().invert(),boxes=[],diagonals=[];root.traverse(m=>{if(m.userData.batchProxy||!m.isMesh||!m.userData.sourceBox)return;for(let q=m;q&&q!==root;q=q.parent)if(excluded.has(q)||q.userData.target)return;const mat=inverse.clone().multiply(m.matrixWorld),e=mat.elements,axisAligned=[0,1,2].every(r=>[0,1,2].filter(c=>Math.abs(e[c*4+r])>eps).length===1),bb=new THREE.Box3().setFromBufferAttribute(m.userData.sourceBox.attributes.position).applyMatrix4(mat);if(axisAligned)boxes.push(bb);else diagonals.push({m,mat});});
 for(const {m,mat}of diagonals){const source=m.userData.sourceBox,p=source.attributes.position,index=source.index,back=mat.clone().invert(),own=new THREE.Box3().setFromBufferAttribute(p).applyMatrix4(mat),near=boxes.filter(b=>b.intersectsBox(own)),signature=near.map(b=>{const q=b.clone().applyMatrix4(back);return [...q.min.toArray(),...q.max.toArray()].map(v=>Math.round(v/eps)).join(',');}).sort().join('|');if(!force&&m.userData.diagonalSignature===signature)continue;m.userData.diagonalSignature=signature;const pos=[],norm=[];for(let i=0;i<(index?.count??p.count);i+=3){const vs=[0,1,2].map(k=>new THREE.Vector3().fromBufferAttribute(p,index?index.getX(i+k):i+k).applyMatrix4(mat)),n=vs[1].clone().sub(vs[0]).cross(vs[2].clone().sub(vs[0])).normalize();let polygons=[vs];if(Math.abs(n.y)>1-eps){let pieces=[vs.map(v=>[v.x,v.z])];const y=vs[0].y;for(const b of near){if(y<b.min.y-eps||y>b.max.y+eps)continue;pieces=pieces.flatMap(poly=>subtract(poly,[b.min.x,b.min.z,b.max.x,b.max.z]));}polygons=pieces.map(poly=>poly.map(([x,z])=>new THREE.Vector3(x,y,z)));}for(const poly of polygons)for(let k=1;k+1<poly.length;k++){const localN=n.clone().transformDirection(back);for(const v of[poly[0],poly[k],poly[k+1]]){pos.push(...v.clone().applyMatrix4(back).toArray());norm.push(...localN.toArray());}}}const g=new THREE.BufferGeometry();g.setAttribute('position',new THREE.Float32BufferAttribute(pos,3));g.setAttribute('normal',new THREE.Float32BufferAttribute(norm,3));if(!m.geometry.userData.pinnedSurface)m.geometry.dispose();m.geometry=g;}
}
